import sys
from math import log2

def is_power_of_2(n):
    return (n & (n - 1)) == 0

def lexicographicallySmallest(S, k):
    n = len(S)
    if is_power_of_2(n):
        k //= 2
    else:
        k *= 2
    if k > n:
        return '-1'
    stack = []
    for char in S:
        while k and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)
    return ''.join(stack[:n-k])

def main():
    import sys
    input = sys.stdin.read().split()
    S = input[0]
    k = int(input[1])
    result = lexicographicallySmallest(S, k)
    print(result)

if __name__ == "__main__":
    main()
